//    «זו ההודעה שתישלח, בלי שום פרט נוסף:…», «ביטול» / «המשך לשיתוף»; «המשך לשיתוף» → системное окно шаринга; после его закрытия вкладки работают;
//  #6a86f7e8 F-95 (6a86f7e837c38d2b29bd68b9) AC4 — шаринг с главной/תהילים через системное окно;
//  #6a86f7fc F-52 (6a86f7fca7ea70e0f9ead0d3) AC1 — «חזק את חברך» → превью → share sheet.
// Скрины: cc02d264-ios-b19-home-share-dialog.png, cc02d264-ios-b19-tehilim-hazek-dialog.png, cc02d264-ios-b19-tehilim-share-sheet.png,
// 6a86f7e8-ios-b19-home-share-sheet.png. Системное окно закрывается свайпом вниз — НИЧЕГО НЕ ОТПРАВЛЯЕТСЯ.
// «текст справа»: если рамка текста на всю ширину окна — позиция букв не видна → @manual-check по скрину.
import { expect } from '@wdio/globals';
import { byText, byTextContains, byLabel, allByText, scrollToText, tapText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { openTehilimChapter, shown } from '../_lib/app-0710.ts';
import {
  SHARE_PREVIEW, expectSharePreview, waitShareSheet, dismissShareSheet, expectTabsSwitch, sideOf, rectOf,
} from '../_lib/app-1310.ts';

/** Заголовок окна: элемент с этим текстом, ближайший СВЕРХУ к строке предпросмотра (на экране есть и кнопка с тем же текстом). */
async function dialogTitle(title: string) {
  const p = await rectOf(byTextContains(SHARE_PREVIEW));
  let best: WebdriverIO.Element | undefined, bestDy = Infinity;
  for (const el of await allByText(title)) {
    if (!(await el.isDisplayed().catch(() => false))) continue;
    const { y } = await el.getLocation();
    if (y < p.y && p.y - y < bestDy) { bestDy = p.y - y; best = el; }
  }
  if (!best) throw new Error(`Нет заголовка окна «${title}» над текстом предпросмотра`);
  return best;
}

async function expectRightAligned(title: string) {
  for (const [what, el] of [['заголовок', await dialogTitle(title)], ['текст', await byTextContains(SHARE_PREVIEW)]] as const) {
    const side = await sideOf(el);
    expect(side).not.toBe('left');
    if (side === 'unknown') console.log(`[SH-01] «${title}»: ${what} — рамка на всю ширину, @manual-check выравнивание вправо по скрину`);
  }
}

/** Открыть окно кнопкой, проверить, «ביטול» закрывает; снова открыть → «המשך לשיתוף» → share sheet → свайп вниз. */
async function shareFlow(open: () => Promise<void>, title: string) {
  await open();
  await expectSharePreview();
  await expectRightAligned(title);

  // «ביטול» закрывает окно, системное окно не открывается.
  await tapText('ביטול');
  await expect(byTextContains(SHARE_PREVIEW)).not.toBeDisplayed();

  // «המשך לשיתוף» → системное окно; закрыть без отправки.
  await open();
  await expectSharePreview();
  await tapText('המשך לשיתוף');
  await waitShareSheet();
  await dismissShareSheet();
  if (await shown(byTextContains(SHARE_PREVIEW))) await tapText('ביטול').catch(() => {});
}

describe('Шаринг: окна «שיתוף» и «חזק את חברך»', () => {
  afterEach(async () => { await toHome(); });

  it('SH-01 Главная «שיתוף»: заголовок/текст справа, «ביטול» закрывает, «המשך לשיתוף» → системное окно (закрыто без отправки) → вкладки работают #cc02d264 #6a86f7e8 @prod-safe @manual-check', async () => {
    await toHome();
    await shareFlow(async () => {
      const btn = await byLabel('שיתוף');
      await btn.waitForDisplayed({ timeout: 20000 });
      await btn.click();
    }, 'שיתוף');
    await expectTabsSwitch();
  });

  it('SH-02 תהילים א׳ «חזק את חברך»: превью справа, «ביטול», «המשך לשיתוף» → системное окно (закрыто) → вкладки работают #cc02d264 #6a86f7fc #6a86f7e8 @prod-safe @manual-check', async () => {
    await openTehilimChapter(1);
    await shareFlow(async () => {
      await (await scrollToText('חזק את חברך', 15)).click();
    }, 'חזק את חברך');
    expect(await byText('תהילים א׳').isExisting()).toBe(true);   // остались в главе
    await expectTabsSwitch();
  });
});
